preset.warp:
// The lines the preset hands the app, drawn here pixel by pixel: smooth at
// any width, and into the picture the glow is made from. The layout is the
// app's services/milkdrop/lineLayer.ts; these numbers must match it.
// Butterchurn reads textures at medium precision, which some drivers (Mesa
// on AMD) take as 16 bits: whole numbers past 2048 lose their last digit,
// and every other stretch went missing. These hold positions and point
// numbers, so all 32.
precision highp sampler2D;
uniform sampler2D sampler_lines;
uniform sampler2D sampler_linetiles;
#define LINES_WIDTH 1024
#define TILES_X 64
#define TILES_Y 36
#define TILE_ENTRIES 192
ivec2 texel(int n) {
  return ivec2(n % LINES_WIDTH, n / LINES_WIDTH);
}
 shader_body {
  vec2 px = uv * texsize.xy;
  ivec2 tile = ivec2(clamp(floor(uv * vec2(TILES_X, TILES_Y)), vec2(0.0), vec2(TILES_X - 1, TILES_Y - 1)));
  vec4 head = texelFetch(sampler_linetiles, texel(tile.y * TILES_X + tile.x), 0);
  int first = int(head.x + 0.5);
  int count = int(head.y + 0.5);
  int entries = TILES_X * TILES_Y * 4 + first;
  vec3 col = vec3(0.0);
  for (int k = 0; k < TILE_ENTRIES; k++) {
    if (k >= count) break;
    int e = entries + k;
    vec4 four = texelFetch(sampler_linetiles, texel(e / 4), 0);
    int i = int(four[e % 4] + 0.5);
    vec4 a = texelFetch(sampler_lines, texel(2 * i), 0);
    vec4 b = texelFetch(sampler_lines, texel(2 * i + 2), 0);
    vec2 pa = a.xy * texsize.xy;
    vec2 ab = b.xy * texsize.xy - pa;
    float t = dot(px - pa, ab) / max(dot(ab, ab), 1e-6);
    // No round ends: the next stretch carries on where this one stops, and
    // two ends on one spot would light it twice.
    if (t < 0.0 || t >= 1.0) continue;
    float cover = clamp(mix(a.z, b.z, t) * 0.5 + 0.5 - length(px - pa - ab * t), 0.0, 1.0);
    if (cover <= 0.0) continue;
    vec3 ca = texelFetch(sampler_lines, texel(2 * i + 1), 0).rgb;
    vec3 cb = texelFetch(sampler_lines, texel(2 * i + 3), 0).rgb;
    col += mix(ca, cb, t) * cover;
  }
  // A trace of the last frame, for a softer glow.
  ret = texture(sampler_main, uv).rgb * 0.3 + col;
}

preset.comp:
uniform sampler2D sampler_cover;
// The theme's accent, one pixel wide (see the app's
// services/milkdrop/textures.ts).
uniform sampler2D sampler_accent;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The cover's main colour, bright and saturated enough to glow; a grey or
// dark cover leaves an ember orange.
vec3 warm() {
  vec3 c = textureLod(sampler_cover, vec2(0.5), 8.0).rgb;
  float hi = max(max(c.r, c.g), c.b);
  float lo = min(min(c.r, c.g), c.b);
  vec3 bright = c / max(hi, 0.02);
  return mix(vec3(1.0, 0.55, 0.25), bright, smoothstep(0.12, 0.35, (hi - lo) / max(hi, 0.02)));
}
float hash13(vec3 p3) {
  p3 = fract(p3 * 0.1031);
  p3 += dot(p3, p3.zyx + 31.32);
  return fract((p3.x + p3.y) * p3.z);
}
float noise3(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = mix(hash13(i), hash13(i + vec3(1, 0, 0)), f.x);
  float b = mix(hash13(i + vec3(0, 1, 0)), hash13(i + vec3(1, 1, 0)), f.x);
  float c = mix(hash13(i + vec3(0, 0, 1)), hash13(i + vec3(1, 0, 1)), f.x);
  float d = mix(hash13(i + vec3(0, 1, 1)), hash13(i + vec3(1, 1, 1)), f.x);
  return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
// Stars on a sphere around the figure, so they turn with the camera.
float stars(vec3 d, float cells) {
  vec3 p = d * cells;
